$t['Final test: complete a sandbox purchase, confirm an HTTP 200 delivery in Stripe, then check the wallet or rental, subscription access and video playback. Also test a declined card and 3D Secure. Never retry a charged payment just because access is still pending.'] = 'Test finale: completa un acquisto in sandbox, verifica una consegna HTTP 200 in Stripe, quindi controlla il wallet o il noleggio, l\'accesso all\'abbonamento e la riproduzione del video. Prova anche una carta rifiutata e 3D Secure. Non ripetere mai un pagamento addebitato solo perché l\'accesso è ancora in sospeso.';
$t['Final test: complete a sandbox purchase with a Personal sandbox buyer, confirm an HTTP 200 webhook delivery in developer.paypal.com, then check the wallet, rental, subscription and video playback. Never retry a paid purchase just because access is still pending.'] = 'Test finale: completa un acquisto in sandbox con un acquirente sandbox Personal, verifica una consegna webhook HTTP 200 su developer.paypal.com, quindi controlla il wallet, il noleggio, l\'abbonamento e la riproduzione del video. Non ripetere mai un acquisto pagato solo perché l\'accesso è ancora in sospeso.';
