$t['The commit identifies the Git revision checked out on this server; local file edits are not included. A Git tag is shown when one points directly to that commit.'] = 'Il commit identifica la revisione Git attiva su questo server; le modifiche locali ai file non sono incluse. Viene mostrato un tag Git quando ne esiste uno che punta direttamente a quel commit.';
$t['The Companion Chat service is not available right now. Ask your site administrator to check the AI plugin connection.'] = 'Il servizio Companion Chat non è disponibile al momento. Chiedi all\'amministratore del sito di controllare la connessione del plugin AI.';
$t['The connection could not be renewed. Please reconnect your account.'] = 'Impossibile rinnovare la connessione. Ricollega il tuo account.';
$t['The connection expired and could not be renewed. Please reconnect your account.'] = 'La connessione è scaduta e non è stato possibile rinnovarla. Ricollega il tuo account.';
$t['The connection to the destination was dropped mid-stream. This may be a temporary network issue; FFMPEG will try to reconnect.'] = 'La connessione alla destinazione si è interrotta durante lo streaming. Potrebbe trattarsi di un problema di rete temporaneo; FFMPEG tenterà di riconnettersi.';
$t['The connection to YouTube was interrupted. The upload was paused and can be resumed.'] = 'La connessione a YouTube si è interrotta. Il caricamento è stato messo in pausa e può essere ripreso.';
$t['The connection was interrupted. Check your account before retrying this subscription.'] = 'La connessione si è interrotta. Controlla il tuo account prima di riprovare questo abbonamento.';
$t['The connection was renewed.'] = 'La connessione è stata rinnovata.';
$t['The connection window was closed before the authorization finished. No account was connected.'] = 'La finestra di connessione è stata chiusa prima del completamento dell\'autorizzazione. Nessun account è stato collegato.';
$t['The converted files were kept. Contact the site administrator to retry the transfer; you do not need to upload the video again.'] = 'I file convertiti sono stati conservati. Contatta l\'amministratore del sito per ritentare il trasferimento; non è necessario caricare di nuovo il video.';
$t['The converted video could not be sent back to this site.'] = 'Non è stato possibile inviare il video convertito a questo sito.';
$t['The customers of the selected card. Search, sort, copy the e-mails or export everything to a spreadsheet.'] = 'I clienti della scheda selezionata. Cerca, ordina, copia le e-mail o esporta tutto in un foglio di calcolo.';
$t['The daily YouTube upload quota of this website was reached. Uploads become available again after midnight Pacific Time. Please try again later.'] = 'È stata raggiunta la quota giornaliera di caricamenti su YouTube di questo sito. I caricamenti saranno di nuovo disponibili dopo la mezzanotte (ora del Pacifico). Riprova più tardi.';
$t['The database version changes only when a database migration is applied. It is not expected to match the release tag or commit.'] = 'La versione del database cambia solo quando viene applicata una migrazione del database. Non è previsto che corrisponda al tag di rilascio o al commit.';
$t['The default'] = 'Il valore predefinito';
$t['The destination RTMP server refused the connection. Check the stream URL and make sure the server is online.'] = 'Il server RTMP di destinazione ha rifiutato la connessione. Controlla l\'URL dello stream e assicurati che il server sia online.';
$t['The destination server requires authentication. Check the stream key.'] = 'Il server di destinazione richiede l\'autenticazione. Controlla la chiave dello stream.';
$t['The destination server returned 403. The stream key may be invalid or expired.'] = 'Il server di destinazione ha restituito 403. La chiave dello stream potrebbe essere non valida o scaduta.';
$t['The destination video was removed or this account cannot edit it. Check the video and account access on the site.'] = 'Il video di destinazione è stato rimosso oppure questo account non può modificarlo. Controlla il video e l\'accesso dell\'account sul sito.';
$t['The download is controlled by the system, there is nothing to check on the user'] = 'Il download è controllato dal sistema, non c\'è niente da controllare sull\'utente';
$t['The download permission is site wide, so there is nothing to check on the video'] = 'Il permesso di download vale per tutto il sito, quindi non c\'è nulla da controllare sul video';
$t['The download permission is site wide, so there is nothing to check onthe video'] = 'Il permesso di download è esteso al sito, quindi non c\'è niente da controllare sul video';
$t['The email is invalid'] = 'L\'e-mail non è valida';
$t['The encoder could not download the original file.'] = 'L\'encoder non è riuscito a scaricare il file originale.';
$t['The encoder could not find this video on the site.'] = 'L\'encoder non è riuscito a trovare questo video sul sito.';
$t['The encoder did not confirm that the video was added to the queue. Please retry.'] = 'L\'encoder non ha confermato che il video è stato aggiunto alla coda. Riprova.';
$t['The encoder is running out of disk space'] = 'L\'encoder sta esaurendo lo spazio su disco';
$t['The encoder reported an unexpected error.'] = 'L\'encoder ha segnalato un errore imprevisto.';
$t['The encoding process stopped unexpectedly, and the automatic retries also failed.'] = 'Il processo di codifica si è interrotto inaspettatamente e anche i tentativi automatici non sono riusciti.';
$t['The encoding queue is stalled'] = 'La coda di codifica è bloccata';
$t['The event purchase could not be completed. Your wallet payment was not deducted. Check your balance before trying again.'] = 'Non è stato possibile completare l\'acquisto dell\'evento. Il pagamento dal portafoglio non è stato addebitato. Controlla il saldo prima di riprovare.';
$t['The file could not be converted. It may be damaged or use a format the encoder does not support.'] = 'Non è stato possibile convertire il file. Potrebbe essere danneggiato o usare un formato non supportato dall\'encoder.';
$t['The file must be an .vtt file!'] = 'Il file deve essere un file .vtt!';
$t['The file must be an .vtt or .srt file!'] = 'Il file deve essere un file .vtt o .srt!';
$t['The final charge uses the duration measured during processing. A connected Marketplace wallet is required.'] = 'L\'addebito finale usa la durata misurata durante l\'elaborazione. È necessario un portafoglio Marketplace collegato.';
$t['The following movie contains materials that are not suitable for children 17 and under.'] = 'Il seguente film contiene materiale non adatto ai minori di 17 anni.';
$t['The following movie contains materials that may not be suitable for children 17 and under.'] = 'Il seguente film contiene materiale che potrebbe non essere adatto ai minori di 17 anni.';
$t['The form to signup will not exists'] = 'Il modulo per iscriversi non esiste';
$t['The gift code has been canceled. If this is unexpected, please contact our support team.'] = 'Il codice regalo è stato annullato. Se non te lo aspettavi, contatta il nostro team di assistenza.';
$t['The gift code is currently inactive. Please check back later or contact support.'] = 'Il codice regalo al momento non è attivo. Riprova più tardi o contatta l\'assistenza.';
$t['The information above corresponds to our official records and confirms the authenticity of this certificate.'] = 'Le informazioni sopra riportate corrispondono ai nostri registri ufficiali e confermano l\'autenticità di questo certificato.';
$t['The input stream contains invalid data. The source HLS may not be ready yet or the stream was interrupted.'] = 'Lo stream in ingresso contiene dati non validi. L\'HLS di origine potrebbe non essere ancora pronto oppure lo stream è stato interrotto.';
$t['The installed PHP package lists both fixes, but this web process still runs the copy loaded before the update. Restart Apache or PHP-FPM.'] = 'Il pacchetto PHP installato include entrambe le correzioni, ma questo processo web esegue ancora la copia caricata prima dell\'aggiornamento. Riavvia Apache o PHP-FPM.';
$t['Their last plans add up to %s'] = 'I loro ultimi piani ammontano a %s';
$t['The list was limited to the first %s results.'] = 'L\'elenco è stato limitato ai primi %s risultati.';
$t['The live service could not complete the request. Please try again.'] = 'Il servizio live non è riuscito a completare la richiesta. Riprova.';
$t['The live that was still being sent to this destination was stopped.'] = 'La diretta ancora in invio a questa destinazione è stata interrotta.';
$t['Theme for Style:'] = 'Tema per lo stile:';
$t['Themes'] = 'Temi';
$t['The number of lines in both columns must be the same'] = 'Il numero di righe in entrambe le colonne deve essere lo stesso';
$t['The original file for this video does not exists anymore'] = 'Il file originale di questo video non esiste più';
$t['The Permissions Plugin is not installed. Please install it if you want to customize the permissions.'] = 'Il plugin per i permessi non è installato. Installalo se vuoi personalizzare i permessi.';
$t['The plugin is disabled'] = 'Il plugin è disabilitato';
$t['The program is empty'] = 'Il programma è vuoto';
$t['The purchase could not be completed. Your wallet payment was not deducted. Check your balance before trying again.'] = 'Non è stato possibile completare l\'acquisto. Il pagamento dal portafoglio non è stato addebitato. Controlla il saldo prima di riprovare.';
$t['There\'s an unknown status associated with this gift code. Please contact support for assistance.'] = 'A questo codice regalo è associato uno stato sconosciuto. Contatta l\'assistenza per ricevere aiuto.';
$t['There, you can set'] = 'Lì, puoi impostare';
$t['There are no notifications'] = 'Non ci sono notifiche';
$t['There are no upcoming events for this channel'] = 'Non ci sono eventi in programma per questo canale';
$t['There are various kinds of media you can integrate here. They are working different'] = 'Ci sono vari tipi di media che puoi integrare qui. Stanno lavorando diversamente';
$t['The recover pass does not match!'] = 'Il passaggio di ripristino non corrisponde!';
$t['The regular form to signin will not exist, if you check this will only have social login or LDAP option'] = 'Il modulo normale per l\'accesso non esisterà, se lo selezioni avrà solo l \'accesso social o l\'opzione LDAP';
$t['There is missing data to recover your password'] = 'Mancano dati per recuperare la password';
$t['There is no Pay Per View plan yet. Create one in the Pay-Per-View plugin, PPV Plans tab.'] = 'Non esiste ancora alcun piano Pay Per View. Creane uno nel plugin Pay-Per-View, scheda Piani PPV.';
$t['There is no plan that can hold videos yet. Create one in the PPV Plans tab, then come back here.'] = 'Non esiste ancora alcun piano che possa contenere video. Creane uno nella scheda Piani PPV, poi torna qui.';
$t['There is no streaming now'] = 'Non c\'è streaming adesso';
$t['The release number and the AVideo database version are independent. Code update status is determined by commit history.'] = 'Il numero di release e la versione del database di AVideo sono indipendenti. Lo stato di aggiornamento del codice è determinato dalla cronologia dei commit.';
$t['The request to the social network failed. Please try again later.'] = 'La richiesta al social network non è riuscita. Riprova più tardi.';
$t['The restreamer server cannot reach the destination. Check network connectivity.'] = 'Il server di restreaming non riesce a raggiungere la destinazione. Controlla la connettività di rete.';
$t['The same alert is repeated at most every %s while the problem continues.'] = 'Lo stesso avviso viene ripetuto al massimo ogni %s finché il problema persiste.';
$t['The same alert is repeated at most every few hours while the problem continues.'] = 'Lo stesso avviso viene ripetuto al massimo ogni poche ore finché il problema persiste.';
$t['The selected camera or microphone is not available. Please choose another device.'] = 'La videocamera o il microfono selezionato non è disponibile. Scegli un altro dispositivo.';
$t['The selected position is highlighted on a real page. Mobile preview changes only the ADs positions; the rest of the page uses your browser device.'] = 'La posizione selezionata è evidenziata su una pagina reale. L\'anteprima mobile cambia solo le posizioni degli annunci; il resto della pagina usa il dispositivo del tuo browser.';
$t['The selected position is outlined on a real page of your site and follows the position you choose below. Mobile preview changes only the ADs positions; the rest of the page uses your browser device.'] = 'La posizione selezionata è evidenziata su una pagina reale del tuo sito e segue la posizione che scegli qui sotto. L\'anteprima mobile modifica solo le posizioni degli annunci; il resto della pagina usa il dispositivo del tuo browser.';
$t['The site is currently offline due to a database issue. We are working to resolve the problem as quickly as possible.'] = 'Il sito è attualmente offline a causa di un problema del database. Stiamo lavorando per risolvere il problema il più rapidamente possibile.';
$t['The site is temporarily unavailable because the server\'s disk is full. We are working on this issue and will be back shortly.'] = 'Il sito è temporaneamente non disponibile perché il disco del server è pieno. Stiamo lavorando al problema e torneremo a breve.';
$t['The site is undergoing maintenance as the server\'s disk is nearing capacity. We are addressing the issue and will be back shortly.'] = 'Il sito è in manutenzione perché il disco del server è quasi pieno. Stiamo risolvendo il problema e torneremo a breve.';
$t['The site refused access. Renew the encoder account access and check its upload permissions.'] = 'Il sito ha rifiutato l\'accesso. Rinnova l\'accesso dell\'account dell\'encoder e controlla i suoi permessi di caricamento.';
$t['The site will display only a login form to un authenticated users'] = 'Il sito mostrerà solo un modulo di accesso agli utenti non autenticati';
$t['The source stream ended. If the live was stopped intentionally this is normal.'] = 'Lo stream di origine è terminato. Se la diretta è stata interrotta intenzionalmente, è normale.';
$t['The split is on: desktop visitors do not see this banner now, they see the left and right halves.'] = 'La divisione è attiva: ora i visitatori da desktop non vedono questo banner, ma le metà sinistra e destra.';
$t['The stream has timestamp discontinuities. This can cause buffering or playback issues on the destination platform.'] = 'Lo stream presenta discontinuità nei timestamp. Ciò può causare buffering o problemi di riproduzione sulla piattaforma di destinazione.';
$t['The subtitle has not been copied to the player yet.'] = 'Il sottotitolo non è ancora stato copiato nel player.';
$t['The subtitle is already on the player.'] = 'Il sottotitolo è già nel player.';
$t['The subtitle was copied to the player.'] = 'Il sottotitolo è stato copiato nel player.';
$t['The subtitle will be available when processing finishes.'] = 'Il sottotitolo sarà disponibile al termine dell\'elaborazione.';
$t['The upload could not be started. Please try again.'] = 'Impossibile avviare il caricamento. Riprova.';
$t['The upload did not start. Click Resume to try again.'] = 'Il caricamento non è partito. Fai clic su Riprendi per riprovare.';
$t['The upload to YouTube started. You can follow its progress below, it continues even if you close this window.'] = 'Il caricamento su YouTube è iniziato. Puoi seguirne l\'avanzamento qui sotto: prosegue anche se chiudi questa finestra.';
$t['The upload was canceled.'] = 'Il caricamento è stato annullato.';
$t['The upload was interrupted. Click Resume to continue from where it stopped.'] = 'Il caricamento è stato interrotto. Fai clic su Riprendi per continuare da dove si era fermato.';
$t['The upload was resumed.'] = 'Il caricamento è stato ripreso.';
$t['the user is inactive'] = 'l\'utente è inattivo';
$t['The username must be an email'] = 'Il nome utente deve essere un\'e-mail';
$t['The user will be able to edit their name and CPF.'] = 'L\'utente potrà modificare il proprio nome e il CPF.';
$t['The video could not be published. Please try again later.'] = 'Impossibile pubblicare il video. Riprova più tardi.';
$t['The video file could not be found on this server, so it cannot be sent to YouTube.'] = 'Il file video non è stato trovato su questo server, quindi non può essere inviato a YouTube.';
$t['The video is empty'] = 'The video is empty';
$t['The video was published.'] = 'Il video è stato pubblicato.';
$t['The website pages do not display this position, so there is nothing to preview.'] = 'Le pagine del sito non mostrano questa posizione, quindi non c\'è nulla da visualizzare in anteprima.';
$t['The website pages do not display this position at the moment. Images saved here are only returned by the API.'] = 'Al momento le pagine del sito non mostrano questa posizione. Le immagini salvate qui vengono restituite solo dall\'API.';
$t['They are likely to leave at renewal time. Invite them back with a suggested course or a live class.'] = 'È probabile che se ne vadano al momento del rinnovo. Invitali a tornare con un corso consigliato o una lezione dal vivo.';
$t['They have paid %s in total'] = 'Hanno pagato %s in totale';
