$t['YouTube did not allow this upload. Reconnect your YouTube account and allow this website to manage your YouTube videos.'] = 'YouTube non ha consentito questo caricamento. Ricollega il tuo account YouTube e consenti a questo sito di gestire i tuoi video YouTube.';
$t['YouTube is receiving too many requests right now. Please wait a few minutes and try again.'] = 'YouTube sta ricevendo troppe richieste in questo momento. Attendi qualche minuto e riprova.';
$t['YouTube rejected the video because it does not follow the YouTube policies.'] = 'YouTube ha rifiutato il video perché non rispetta le norme di YouTube.';
$t['YouTube rejected the video because it is a duplicate of a video already on your channel.'] = 'YouTube ha rifiutato il video perché è un duplicato di un video già presente sul tuo canale.';
$t['YouTube rejected the video because it is longer than your channel allows. Verify your YouTube account to upload longer videos.'] = 'YouTube ha rifiutato il video perché è più lungo di quanto consentito dal tuo canale. Verifica il tuo account YouTube per caricare video più lunghi.';
$t['YouTube rejected the video because of a copyright claim.'] = 'YouTube ha rifiutato il video a causa di una rivendicazione di copyright.';
$t['YouTube returned an unexpected error. Please try again later. If the problem continues, contact the site administrator.'] = 'YouTube ha restituito un errore imprevisto. Riprova più tardi. Se il problema persiste, contatta l\'amministratore del sito.';
$t['YouTube URL'] = 'URL YouTube';
